import { afterEach, describe, expect, it, vi } from "vitest";
import type { AudioTrack, VideoTrack } from "../../src/types";
import { stubBrowserGlobals } from "../helpers/browser-globals";

// dist/wasm/movi.js is generated by build:wasm (Docker/4090) and is absent in
// the unit-test CI job (dist/ is gitignored). MoviPlayer's module graph imports
// it eagerly via FFmpegLoader; this test never loads/runs the WASM, so stub the
// module so importing the player graph resolves without the built artifact.
vi.mock("../../dist/wasm/movi.js", () => ({ default: vi.fn(async () => ({})) }));

vi.mock("dashjs", () => ({ MediaPlayer: vi.fn() }));
vi.mock("shaka-player/dist/shaka-player.compiled", () => ({
  default: {
    Player: { isBrowserSupported: vi.fn(() => false) },
    polyfill: { installAll: vi.fn() },
    net: { NetworkingEngine: { RequestType: { LICENSE: 1 } } },
  },
}));

const videoTrack: VideoTrack = {
  id: 0,
  type: "video",
  codec: "hevc",
  width: 1920,
  height: 1080,
  frameRate: 24,
};

const flacTrack: AudioTrack = {
  id: 1,
  type: "audio",
  codec: "flac",
  codecId: 86028,
  channels: 2,
  sampleRate: 48000,
};

afterEach(() => {
  vi.unstubAllGlobals();
});

/**
 * A player mid-rebuffer with NOTHING decoded on the video side and an audio
 * cushion that overshot its target before the stall.
 *
 * `audioBuffered` is the only knob: everything else is the shape of a real
 * rebuffer — clock paused, renderer suspended, video queues empty.
 */
function rebufferingPlayer(player: unknown, audioBuffered: number) {
  const readPacket = vi.fn(async () => null);
  Object.assign(player as Record<string, unknown>, {
    demuxer: { readPacket },
    mediaInfo: { duration: 1422, videoFrameRate: 24 },
    wasPlayingBeforeRebuffer: true,
    _bufferingEntryTime: performance.now() - 1000,
    _playStartTime: performance.now() - 20_000,
    waitingForVideoSync: false,
    seekTargetTime: -1,
    seekDemuxAheadTime: -1,
    justSeeked: false,
    seekTime: 0,
    disableAudio: false,
    muted: false,
    eofReached: false,
    demuxInFlight: false,
    isBackgrounded: false,
    isPiPActive: false,
    _primingAudio: false,
    videoDecoder: {
      isSoftware: false,
      queueSize: 0,
      isWaitingForKeyframe: false,
      isRecentlyRecovering: () => false,
      keyframeWaitMs: () => 0,
      flush: vi.fn(),
    },
    audioDecoder: {
      isSoftware: true,
      queueSize: 0,
      getStats: () => ({ worker: { queueDepth: 0 } }),
      canBatch: () => false,
      decode: vi.fn(),
    },
    videoRenderer: {
      getQueueSize: () => 0,
      stopPresentationLoop: vi.fn(),
      getHeadFrameTime: () => -1,
    },
    audioRenderer: {
      getBufferedDuration: () => audioBuffered,
      isRebuffering: () => false,
      isDroppingAudio: () => false,
      isUnderrunning: () => false,
      getAudioClock: () => -1,
      getMaxScheduledMediaTime: () => 0,
      resumeFromBuffering: vi.fn(),
    },
  });
  return readPacket;
}

describe("rebuffer unlock", () => {
  /**
   * Black-box regression (real OpenList, headless Chrome, HEVC Main10 + FLAC):
   * the gate that stops reading while audio is over its cushion also has to let
   * go during a rebuffer, because a rebuffer is exactly when the cushion CANNOT
   * drain — the renderer is suspended and the clock is paused, so whatever
   * `audioBuffered` was at the stall is what it stays. Latching there deadlocks:
   * no reads, so no frame; no frame, so no resume; no resume, so no drain.
   *
   * The observed run had 8.6s of audio buffered against a 5s target and never
   * left "buffering" — `media clock rate 0.340 during steady playback`.
   */
  it("reads on while a rebuffer has no video at all, however far ahead audio got", async () => {
    stubBrowserGlobals();
    const { MoviPlayer } = await import("../../src/core/MoviPlayer");
    const player = new MoviPlayer({});
    player.trackManager.setTracks([videoTrack, flacTrack]);

    const stateManager = (player as any).stateManager;
    stateManager.setState("loading");
    stateManager.setState("ready");
    stateManager.setState("playing");
    stateManager.setState("buffering");

    // 8.6s buffered against the 5.0s software-audio target: past the 1s
    // overshoot the unlock used to require.
    const readPacket = rebufferingPlayer(player, 8.6);

    await (player as any).processLoop();

    expect(readPacket).toHaveBeenCalled();
  }, 20_000);

  it("still lets audio's cushion stop the loop when video is playing normally", async () => {
    stubBrowserGlobals();
    const { MoviPlayer } = await import("../../src/core/MoviPlayer");
    const player = new MoviPlayer({});
    player.trackManager.setTracks([videoTrack, flacTrack]);

    const stateManager = (player as any).stateManager;
    stateManager.setState("loading");
    stateManager.setState("ready");
    stateManager.setState("playing");

    const readPacket = rebufferingPlayer(player, 8.6);
    // Not a rebuffer: playing, with decoded frames in hand. The cushion is over
    // target, so the loop must back off — that ceiling is the whole point.
    Object.assign(player as any, {
      wasPlayingBeforeRebuffer: false,
      videoRenderer: {
        getQueueSize: () => 30,
        stopPresentationLoop: vi.fn(),
        getHeadFrameTime: () => 12,
      },
    });

    await (player as any).processLoop();

    expect(readPacket).not.toHaveBeenCalled();
  }, 20_000);
});
